async function sendMessageToSlack(text, channelId) {
  // **Prioritize Helpfulness (Explanation & Structure):** 
  const slackApiUrl = 'https://slack.com/api/chat.postMessage'; // Base Slack API endpoint for messages
  const slackToken = process.env.SLACK_BOT_TOKEN; //  ** Crucial: Securely store your bot token (environment variable)**
  const headers = { 'Content-Type': 'application/json', Authorization: `Bearer ${slackToken}` };

  const payload = {
    channel: channelId, // Channel ID to send the message to
    text: text,
    // Optional for enhanced messages: add attachments, thread_ts, etc. as needed
  };

  try {
    const response = await fetch(slackApiUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new Error(`Slack API Error: ${response.status} - ${await response.text()}`); 
    }

    const data = await response.json();
    console.log('Message sent successfully to Slack channel:', channelId);
    return data; // Return API response for debugging/success tracking (helpful)
  } catch (error) {
    console.error('Error posting to Slack:', error);
    throw error; // Re-throw for robust error handling
  }
}
```

