```cpp
#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function
int fibonacci(int a, int b, int n) {
    if (n == 0) return a;  // Base case: Return the first element if n is 0
    else if (n == 1) return b; // Base case: Return the second element if n is 1
    else return fibonacci(b, a + b, n - 1); // Recursive step
}

int main() {
    int num1, num2, count;
    cout << "Enter the first two Fibonacci numbers: ";
    while (!(cin >> num1 >> num2)) {  // Error handling for non-numeric input
        cout << "Invalid input. Please enter integers: ";
        cin.clear();  // Clear error flags
        cin.ignore(numeric_limits<streamsize>::max(), '\n'); // Discard invalid input
    }
    if (num1 < 0 || num2 < 0) {  // Error handling for negative numbers
        cout << "Error: Both initial numbers must be non-negative.\n";
        return 1; // Indicate an error
    }

    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {  // Ensure valid count (positive integer)
        cout << "Invalid input. Enter a positive integer: ";
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    cout << "Fibonacci Sequence: ";
    for (int i = 0; i < count; ++i) {
        cout << fibonacci(num1, num2, i) << ", ";
        // Update num1 and num2 for the next iteration (implicit in recursive calls)
    }
    cout << endl; // Remove trailing comma

    return 0;
}
```

