    {
        _baseUrl = baseUrl;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        _authTokenHandler = authTokenHandler ?? (req => { }); // Default to no auth if not provided
    }

    protected virtual async Task<HttpResponseMessage> MakeRequestAsync(HttpMethod method, string relativeUrl, object content = null, Dictionary<string, string> headers = null)
    {
        var request = new HttpRequestMessage(method, relativeUrl)
        {
            Content = content != null ? new StringContent(JsonConvert.SerializeObject(content), System.Text.Encoding.UTF8, "application/json") : null
        };

        // Apply Auth Token Handling
        _authTokenHandler(request); 

        headers?.ToList().ForEach(h => request.Headers.Add(h.Key, h.Value)); // Add custom headers

        return await _client.SendAsync(request);
    }

    // Generic Methods (Extend with more as needed)
    public async Task<T> GetAsync(string relativeUrl, Dictionary<string, string> queryParameters = null, Dictionary<string, string> headers = null)
    {
        var uri = BuildUriWithQuery(relativeUrl, queryParameters);
        var response = await MakeRequestAsync(HttpMethod.Get, uri, headers: headers);
        return await HandleResponse<T>(response);
    }

    public async Task<T> PostAsync<TData>(string relativeUrl, TData data, Dictionary<string, string> headers = null)
    {
        var response = await MakeRequestAsync(HttpMethod.Post, relativeUrl, JsonConvert.SerializeObject(data), headers);
        return await HandleResponse<T>(response);
    }

