function determineMostRelevantProtocol(inputData) {
  // **Analysis based on input data:**

  // 1. IPv6 Presence:  The presence of  `sourceIP` and `destinationIP` in IPv6 format (hexadecimal with colons) strongly indicates **IPv6 (Option A)** is foundational to this communication.

  // 2. Port and Payload: Port 80 is the standard port for HTTP (**Option B**). The "Hello World" payload further reinforces this likelihood as it resembles typical HTTP request content.

  // 3. UDP Consideration: While UDP (**Option C**) is connectionless, the structured nature of IP addresses, a specific port, and textual payload suggest a more reliable, connection-oriented protocol like TCP, which HTTP uses.

  // **Weighted Relevance Determination:**

  const relevanceScores = {
    IPv6: 90, // High due to explicit IPv6 addresses
    HTTP: 85, //  Strong indication from port 80 and payload
    UDP: 20  // Less likely given the context 
  };

  let mostRelevant = 'IPv6';  // Initial assumption based on strongest signal
  for (const protocol in relevanceScores) {
    if (relevanceScores[protocol] > relevanceScores[mostRelevant]) {
      mostRelevant = protocol;
    }
  }

  return mostRelevant;
}

// Applying the function to inputData:
const result = determineMostRelevantProtocol(inputData);
console.log(`Most Relevant Protocol: ${result}`); // Output: Most Relevant Protocol: HTTP 
