import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { PrismaService } from './prisma.service';
import * as _ from 'lodash';

const PERMISSIONS = [
  'READ_USERS',
  'CREATE_USERS',
  'UPDATE_USERS',
  'DELETE_USERS',
  'READ_PRODUCTS',
  'CREATE_PRODUCTS',
  'UPDATE_PRODUCTS',
  'DELETE_PRODUCTS',
  // Add more permissions...
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private prisma: PrismaService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // No roles specified, allow access

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user || !user.role) throw new UnauthorizedException('Invalid authentication');

    const userPermissions = await this.prisma.user.findUnique({
      where: { id: user.id },
      select: { roles: true },
    });
    const hasRequiredRole = _.intersection(requiredRoles, userPermissions?.roles || []).length > 0;

    return hasRequiredRole;
  }
}
```

**Explanation (for understanding, NOT part of the final `index.js`):**

1. **`PERMISSIONS` Array:** Defines a central list of permission names for the application's authorization logic. Extend this with your specific needs.
2. **`RolesGuard`:**
   - Injects `Reflector` to fetch role requirements from decorators (e.g., `@UseGuards(RolesGuard({ roles: ['ADMIN'] }))` on routes).
   - Injects `PrismaService` to query user roles from the database.
   - **`canActivate`:**
     - Checks for required roles using `Reflector`. If none defined, allows access.
     - Retrieves user data (including role) from the request context.
     - Queries the database for the user's assigned roles using Prisma.

